; Pop-up keyboard reader: polls 64h/60h directly (redrawing the clock while idle), treats E0h as a prefix (40:B6 bit 7), maps extended scancodes (setup_extended_scancodes) to AL=0/AH=scancode, digit keys 02h-0Bh to '1'..'0', Backspace to 08h; unknown keys beep (setup_key_default).
popup_read_key:
        push cx                                  ; 1539
        push di                                  ; 153A
        push es                                  ; 153B

loc_153C:
        in al, 0x64                              ; 153C  port 64h: KBC command/status
        test al, 1                               ; 153E
        jne loc_1550                             ; 1540
        mov al, 0xc                              ; 1542
        call cmos_hw_read                        ; 1544
        test al, 0x10                            ; 1547
        je loc_153C                              ; 1549
        call setup_draw_time_date                ; 154B
        jmp loc_153C                             ; 154E

loc_1550:
        in al, 0x60                              ; 1550  port 60h: KBC data
        cmp al, 0xe0                             ; 1552
        jne loc_1566                             ; 1554
        push ax                                  ; 1556
        push ds                                  ; 1557
        mov ax, 0x40                             ; 1558
        mov ds, ax                               ; 155B
        or byte [0xb6], 0x80                     ; 155D
        pop ds                                   ; 1562
        pop ax                                   ; 1563
        jmp loc_153C                             ; 1564

loc_1566:
        or al, al                                ; 1566
        js loc_153C                              ; 1568
        push bx                                  ; 156A
        mov bx, cs                               ; 156B
        mov es, bx                               ; 156D
        pop bx                                   ; 156F
        mov cx, 0xe                              ; 1570
        mov di, 0x15e9                           ; 1573
        repne scasb                              ; 1576
        je loc_15A5                              ; 1578
        mov cx, 7                                ; 157A
        mov di, 0x15f7                           ; 157D
        repne scasb                              ; 1580
        je loc_15DC                              ; 1582
        cmp al, 2                                ; 1584
        jl loc_159C                              ; 1586
        cmp al, 0xb                              ; 1588
        ja loc_159C                              ; 158A
        mov ah, al                               ; 158C
        cmp al, 0xb                              ; 158E
        jne loc_1596                             ; 1590
        mov al, 0x30                             ; 1592
        jmp loc_15E5                             ; 1594

loc_1596:
        dec al                                   ; 1596
        add al, 0x30                             ; 1598
        jmp loc_15E5                             ; 159A

loc_159C:
        cmp al, 0x2a                             ; 159C
        je loc_153C                              ; 159E
        call setup_key_default                   ; 15A0
        jmp loc_153C                             ; 15A3

loc_15A5:
        push ax                                  ; 15A5
        push ds                                  ; 15A6
        mov ax, 0x40                             ; 15A7
        mov ds, ax                               ; 15AA
        test byte [0xb6], 0x80                   ; 15AC
        jne loc_15CF                             ; 15B1
        test byte [0x17], 0x20                   ; 15B3
        je loc_15CF                              ; 15B8
        cmp al, 0x3f                             ; 15BA
        je loc_15CF                              ; 15BC
        cmp al, 0x40                             ; 15BE
        je loc_15CF                              ; 15C0
        and byte [0xb6], 0x7f                    ; 15C2
        pop ds                                   ; 15C7
        pop ax                                   ; 15C8
        call setup_key_default                   ; 15C9
        jmp loc_153C                             ; 15CC

loc_15CF:
        and byte [0xb6], 0x7f                    ; 15CF
        pop ds                                   ; 15D4
        pop ax                                   ; 15D5
        mov ah, al                               ; 15D6
        mov al, 0                                ; 15D8
        jmp loc_15E5                             ; 15DA

loc_15DC:
        mov ah, al                               ; 15DC
        cmp ah, 0xe                              ; 15DE
        jne loc_15E5                             ; 15E1
        mov al, 8                                ; 15E3

loc_15E5:
        pop es                                   ; 15E5
        pop di                                   ; 15E6
        pop cx                                   ; 15E7
        ret                                      ; 15E8

; Scancode list H K M P ; < ? @ E R S > I Q (cursor keys, F1-F6, Ins/Del, PgUp/PgDn) + 01 39 4E 4A 0C 0D - the keys the SETUP key handler recognises.
setup_extended_scancodes:
; [data] setup_extended_scancodes
        db 0x48, 0x4B, 0x4D, 0x50, 0x3B, 0x3C, 0x3F, 0x40, 0x45, 0x52, 0x53, 0x3E, 0x49, 0x51, 0x01, 0x39 ; 15E9 HKMP;<?@ERS>IQ.9
        db 0x4E, 0x4A, 0x0C, 0x0D, 0x0E ; 15F9 NJ...

; ZF clear when 40:B6 bit 1 is set - SETUP was started as PhoenixMISER's pop-up (bda_popup_mark_set); keyboard then comes straight from the KBC (popup_read_key) instead of INT 16h.
setup_in_popup:
        push ax                                  ; 15FE
        push ds                                  ; 15FF
        mov ax, 0x40                             ; 1600
        mov ds, ax                               ; 1603
        test byte [0xb6], 2                      ; 1605
        pop ds                                   ; 160A
        pop ax                                   ; 160B
        ret                                      ; 160C

; Derives a bit mask from CX (video ROM size in 32 KB units, video_rom_size_32k_units) and updates CMOS 48h in the shadow (shadow-RAM configuration, best guess), then redraws the following fields.
setup_shadow_cmos48_update:
        call video_rom_size_32k_units            ; 160D
        cmp cx, 0                                ; 1610
        jne loc_1616                             ; 1613
        inc cx                                   ; 1615

loc_1616:
        mov bh, al                               ; 1616
        mov al, 0x48                             ; 1618
        call cmos_shadow_read                    ; 161A
        mov bl, 1                                ; 161D
        shl bl, cl                               ; 161F
        dec bl                                   ; 1621
        not bl                                   ; 1623
        and al, bl                               ; 1625

; Continuation: BH bit 0 selects set/clear, writes CMOS 48h, setup_redraw_following_fields, setup_cmos_read_field.
setup_shadow_cmos48_tail:
        and bh, 1                                ; 1627
        je loc_1630                              ; 162A
        not bl                                   ; 162C
        or al, bl                                ; 162E

loc_1630:
        mov bh, al                               ; 1630
        mov al, 0x48                             ; 1632
        call cmos_shadow_write                   ; 1634
        call setup_redraw_following_fields       ; 1637
        call setup_cmos_read_field               ; 163A
        ret                                      ; 163D

; ES := C000h then option_rom_size_at_es.
video_rom_size_32k_units:
        push es                                  ; 163E
        mov bx, 0xc000                           ; 163F
        mov es, bx                               ; 1642

; CX := 0 when ES:0000 is not 55AAh, else rom_size_from_header.
option_rom_size_at_es:
        mov bx, 0                                ; 1644
        mov bx, word [es:bx]                     ; 1647
        cmp bx, 0xaa55                           ; 164A
        je rom_size_from_header                  ; 164E
        mov cx, 0                                ; 1650
        pop es                                   ; 1653
        ret                                      ; 1654

; CX := ES:[2] (512-byte units) / 64 rounded up = size in 32 KB blocks.
rom_size_from_header:
        mov bx, 2                                ; 1655
        mov cl, byte [es:bx]                     ; 1658
        xor ch, ch                               ; 165B
        mov bx, cx                               ; 165D
        shr cx, 5                                ; 165F
        and bx, 0x1f                             ; 1662
        cmp bx, 0                                ; 1665
        je loc_166D                              ; 1668
        add cx, 1                                ; 166A

loc_166D:
        pop es                                   ; 166D
        ret                                      ; 166E

; Unless [bp+2E] bit 1: redraws the next CX-1 field records (handler +6 and setup_draw_field).
setup_redraw_following_fields:
        test byte [bp + 0x2e], 2                 ; 166F
        jne loc_1690                             ; 1673
        cmp cx, 1                                ; 1675
        jle loc_1690                             ; 1678
        dec cx                                   ; 167A
        push cx                                  ; 167B

loc_167C:
        push cx                                  ; 167C
        inc byte [bp + 0x2b]                     ; 167D
        call setup_field_record                  ; 1680
        call setup_field_handler_6               ; 1683
        call setup_draw_field                    ; 1686
        pop cx                                   ; 1689
        loop loc_167C                            ; 168A
        pop cx                                   ; 168C
        sub byte [bp + 0x2b], cl                 ; 168D

loc_1690:
        ret                                      ; 1690

; Words 0Ch, 0..5 (field index table, best guess) followed by a 4-byte stub.
setup_word_table_1691:
; [data] setup_word_table_1691
        db 0x0C, 0x00, 0x00, 0x00, 0x01, 0x00, 0x02, 0x00, 0x03, 0x00, 0x04, 0x00, 0x05, 0x00, 0xE8, 0x01 ; 1691 ................
        db 0x00, 0xC3 ; 16A1 ..

; Draws the gauge with the test value C3h (76 %) - debugging leftover.
setup_draw_gauge_test:
        push ax                                  ; 16A3
        push bx                                  ; 16A4
        push dx                                  ; 16A5
        mov al, 0                                ; 16A6
        mov al, 0xc3                             ; 16A8

; AL (0-255) -> percentage (scale_to_percent), printed at row 10h col 47h-49h with attribute 70h (draw_percent_at_col_47), then draw_gauge_bar_cmos13. Best guess: battery level display of the Power page.
setup_draw_gauge:
        call scale_to_percent                    ; 16AA
        mov dh, 0x10                             ; 16AD
        push ax                                  ; 16AF
        call draw_percent_at_col_47              ; 16B0
        pop ax                                   ; 16B3
        mov bl, 0xc                              ; 16B4
        call draw_gauge_bar_cmos13               ; 16B6
        pop dx                                   ; 16B9
        pop bx                                   ; 16BA
        pop ax                                   ; 16BB
        ret                                      ; 16BC

; AL := round(AL*100/255).
scale_to_percent:
        push cx                                  ; 16BD
        and ax, 0xff                             ; 16BE
        mov cl, 0x64                             ; 16C1
        mul cl                                   ; 16C3
        mov cl, 0xff                             ; 16C5
        div cl                                   ; 16C7
        cmp ah, 0x80                             ; 16C9
        jb loc_16D0                              ; 16CC
        inc al                                   ; 16CE

loc_16D0:
        xor ah, ah                               ; 16D0
        pop cx                                   ; 16D2
        ret                                      ; 16D3

; Prints the 1-3 digit percentage at cursor row DH, columns 47h-49h.
draw_percent_at_col_47:
        push bx                                  ; 16D4
        push cx                                  ; 16D5
        cmp al, 0x64                             ; 16D6
        jb loc_16EB                              ; 16D8
        mov dl, 0x47                             ; 16DA
        call int10_set_cursor_dx                 ; 16DC
        push ax                                  ; 16DF
        mov al, 0x31                             ; 16E0
        mov cx, 1                                ; 16E2
        mov bl, 0x70                             ; 16E5
        call int10_write_char_attr               ; 16E7
        pop ax                                   ; 16EA

loc_16EB:
        mov dl, 0x48                             ; 16EB
        call int10_set_cursor_dx                 ; 16ED
        mov cl, 0xa                              ; 16F0
        div cl                                   ; 16F2
        push ax                                  ; 16F4
        and ax, 0xf                              ; 16F5
        cmp al, 9                                ; 16F8
        jb loc_16FE                              ; 16FA
        sub al, 0xa                              ; 16FC

loc_16FE:
        add al, 0x30                             ; 16FE
        mov cx, 1                                ; 1700
        mov bl, 0x70                             ; 1703
        call int10_write_char_attr               ; 1705
        pop ax                                   ; 1708
        mov dl, 0x49                             ; 1709
        call int10_set_cursor_dx                 ; 170B
        xchg ah, al                              ; 170E
        and ax, 0xf                              ; 1710
        add al, 0x30                             ; 1713
        mov cx, 1                                ; 1715
        mov bl, 0x70                             ; 1718
        call int10_write_char_attr               ; 171A
        pop cx                                   ; 171D
        pop bx                                   ; 171E
        ret                                      ; 171F

; Shadow CMOS 13h -> 0/1/2.. -> prints that many 08h characters at col 13h (bar).
draw_gauge_bar_cmos13:
        push bx                                  ; 1720
        push cx                                  ; 1721
        push bx                                  ; 1722
        mov dl, 0x13                             ; 1723
        call int10_set_cursor_dx                 ; 1725
        pop bx                                   ; 1728
        cmp al, 0                                ; 1729
        je loc_173E                              ; 172B
        cmp al, 1                                ; 172D
        ja loc_1733                              ; 172F
        inc al                                   ; 1731

loc_1733:
        shr al, 1                                ; 1733
        mov cl, al                               ; 1735
        xor ch, ch                               ; 1737
        mov al, 8                                ; 1739
        call int10_write_char_attr               ; 173B

loc_173E:
        pop cx                                   ; 173E
        pop bx                                   ; 173F
        ret                                      ; 1740

; INT 10h AH=02h page 0, DX = row/col.
int10_set_cursor_dx:
        push ax                                  ; 1741
        push bx                                  ; 1742
        push dx                                  ; 1743
        mov ah, 2                                ; 1744
        xor bh, bh                               ; 1746
        int 0x10                                 ; 1748  video
        pop dx                                   ; 174A
        pop bx                                   ; 174B
        pop ax                                   ; 174C
        ret                                      ; 174D

; INT 10h AH=09h (AL char, BL attribute, CX count).
int10_write_char_attr:
        push ax                                  ; 174E
        push bx                                  ; 174F
        push cx                                  ; 1750
        xor bh, bh                               ; 1751
        mov ah, 9                                ; 1753
        int 0x10                                 ; 1755  video
        pop cx                                   ; 1757
        pop bx                                   ; 1758
        pop ax                                   ; 1759
        ret                                      ; 175A

; AL := CMOS 4Eh; bit 0 -> AL (SETUP helper).
setup_cmos_4E_bit0:
        mov al, 0x4e                             ; 175B
        call cmos_shadow_read                    ; 175D
        push cx                                  ; 1760
        and al, 1                                ; 1761
        mov cl, 0                                ; 1763
        shr al, cl                               ; 1765
        pop cx                                   ; 1767
        xor ah, ah                               ; 1768
        ret                                      ; 176A

; VersaPort field +: option index 0-4 external floppy types, 5/6 parallel standard/bidirectional, 7/8 EPP 1.7/1.9 (skips gaps), then versaport_apply_option.
versaport_next_option:
        call field_value_get                     ; 176B
        inc al                                   ; 176E
        cmp al, 5                                ; 1770
        jbe loc_1788                             ; 1772
        cmp al, 7                                ; 1774
        ja loc_1780                              ; 1776
        cmp al, 6                                ; 1778
        je loc_178E                              ; 177A
        mov al, 5                                ; 177C
        jmp loc_178E                             ; 177E

loc_1780:
        cmp al, 8                                ; 1780
        je loc_178E                              ; 1782
        mov al, 7                                ; 1784
        jmp loc_178E                             ; 1786

loc_1788:
        cmp al, 5                                ; 1788
        jb loc_178E                              ; 178A
        xor al, al                               ; 178C

loc_178E:
        push bx                                  ; 178E
        call field_value_set                     ; 178F
        pop bx                                   ; 1792
        call versaport_apply_option              ; 1793
        ret                                      ; 1796

; VersaPort field -: previous option (wraps 0 -> 4, skips the gaps), then versaport_apply_option.
versaport_prev_option:
        call field_value_get                     ; 1797
        dec al                                   ; 179A
        cmp al, 0                                ; 179C
        jge loc_17A4                             ; 179E
        mov al, 4                                ; 17A0
        jmp loc_17B6                             ; 17A2

loc_17A4:
        cmp al, 4                                ; 17A4
        je loc_17AF                              ; 17A6
        cmp al, 6                                ; 17A8
        je loc_17B4                              ; 17AA
        jmp loc_17B6                             ; 17AC
; [data] alignment pad (nop / xchg bx,bx)
        db 0x90 ; 17AE .

loc_17AF:
        mov al, 6                                ; 17AF
        jmp loc_17B6                             ; 17B1
; [data] alignment pad (nop / xchg bx,bx)
        db 0x90 ; 17B3 .

loc_17B4:
        mov al, 8                                ; 17B4

loc_17B6:
        push bx                                  ; 17B6
        call field_value_set                     ; 17B7
        pop bx                                   ; 17BA
        call versaport_apply_option              ; 17BB
        ret                                      ; 17BE

; Option 0-4 -> CMOS 10h low nibble (external floppy type); 5/6 -> CMOS 59h bit 2 (bidirectional); 7/8 -> CMOS 59h bit 3 (EPP 1.9); updates the shadow checksum fields.
versaport_apply_option:
        cmp al, 6                                ; 17BF
        ja loc_17FD                              ; 17C1
        cmp al, 4                                ; 17C3
        ja loc_17DE                              ; 17C5
        push ax                                  ; 17C7
        mov al, 0x10                             ; 17C8
        call cmos_shadow_read                    ; 17CA
        mov bh, al                               ; 17CD
        pop ax                                   ; 17CF
        and bh, 0xf0                             ; 17D0
        or bh, al                                ; 17D3
        mov al, 0x10                             ; 17D5
        call cmos_shadow_write                   ; 17D7
        call setup_cmos_write_field              ; 17DA
        ret                                      ; 17DD

loc_17DE:
        sub al, 5                                ; 17DE
        mov cl, 2                                ; 17E0
        shl al, cl                               ; 17E2
        and al, 4                                ; 17E4
        push ax                                  ; 17E6
        mov al, 0x59                             ; 17E7
        call cmos_shadow_read                    ; 17E9
        mov bh, al                               ; 17EC
        pop ax                                   ; 17EE
        and bh, 0xfb                             ; 17EF
        or bh, al                                ; 17F2
        mov al, 0x59                             ; 17F4
        call cmos_shadow_write                   ; 17F6
        call setup_cmos_read_field               ; 17F9
        ret                                      ; 17FC

loc_17FD:
        sub al, 7                                ; 17FD
        mov cl, 3                                ; 17FF
        shl al, cl                               ; 1801
        and al, 8                                ; 1803
        push ax                                  ; 1805
        mov al, 0x59                             ; 1806
        call cmos_shadow_read                    ; 1808
        mov bh, al                               ; 180B
        pop ax                                   ; 180D
        and bh, 0xf7                             ; 180E
        or bh, al                                ; 1811
        mov al, 0x59                             ; 1813
        call cmos_shadow_write                   ; 1815
        call setup_cmos_read_field               ; 1818
        ret                                      ; 181B

; CMOS 59h bits 0-1: 1 = external floppy -> option = CMOS 10h low nibble (0-6); 0 = parallel -> 5 + bit 2; 2 = EPP -> 7 + bit 3. Stores the option in the field value array.
versaport_read_option:
        mov al, 0x59                             ; 181C
        call cmos_shadow_read                    ; 181E
        and al, 3                                ; 1821
        je loc_1848                              ; 1823
        cmp al, 2                                ; 1825
        je loc_185F                              ; 1827
        mov al, 0x10                             ; 1829
        call cmos_shadow_read                    ; 182B
        and al, 0xf                              ; 182E
        mov cl, 0                                ; 1830
        shr al, cl                               ; 1832
        cmp al, 6                                ; 1834
        jbe loc_183A                             ; 1836
        mov al, 0                                ; 1838

loc_183A:
        xor bh, bh                               ; 183A
        mov bl, byte [bp + 0x2b]                 ; 183C
        mov di, word [bp + 0x2c]                 ; 183F
        add di, bx                               ; 1842
        mov byte [ss:di], al                     ; 1844
        ret                                      ; 1847

loc_1848:
        mov al, 0x59                             ; 1848
        call cmos_shadow_read                    ; 184A
        and al, 4                                ; 184D
        mov cl, 2                                ; 184F
        shr al, cl                               ; 1851
        cmp al, 1                                ; 1853
        jbe loc_1859                             ; 1855
        mov al, 0                                ; 1857

loc_1859:
        add al, 6                                ; 1859
        dec al                                   ; 185B
        jmp loc_183A                             ; 185D

loc_185F:
        mov al, 0x59                             ; 185F
        call cmos_shadow_read                    ; 1861
        and al, 8                                ; 1864
        mov cl, 3                                ; 1866
        shr al, cl                               ; 1868
        cmp al, 1                                ; 186A
        jbe loc_1870                             ; 186C
        mov al, 1                                ; 186E

loc_1870:
        add al, 7                                ; 1870
        jmp loc_183A                             ; 1872

