        out 0x80, al                             ; 9BA2  port 80h: POST diagnostic code
        mov al, 0                                ; 9BA4
        call speed_hook_stub                     ; 9BA6
        add sp, 2                                ; 9BA9
        ret                                      ; 9BAC

