        mov dx, 0x24                             ; 9BAD
        mov ax, 0x200                            ; 9BB0
        out dx, ax                               ; 9BB3
        out 0xed, al                             ; 9BB4
        mov dx, 0x26                             ; 9BB6
        in ax, dx                                ; 9BB9
        test ax, 0x1000                          ; 9BBA
        je loc_9C02                              ; 9BBD
        mov dx, 0x24                             ; 9BC1
        mov ax, 0x207                            ; 9BC4
        out dx, ax                               ; 9BC7
        out 0xed, al                             ; 9BC8
        mov dx, 0x26                             ; 9BCA
        in ax, dx                                ; 9BCD
        or ax, 0x1000                            ; 9BCE
        push ax                                  ; 9BD1
        mov dx, 0x24                             ; 9BD2
        mov ax, 0x207                            ; 9BD5
        out dx, ax                               ; 9BD8
        out 0xed, al                             ; 9BD9
        mov dx, 0x26                             ; 9BDB
        pop ax                                   ; 9BDE
        out dx, ax                               ; 9BDF
        call hd_autodetect_patch_table           ; 9BE0
        mov dx, 0x24                             ; 9BE3
        mov ax, 0x207                            ; 9BE6
        out dx, ax                               ; 9BE9
        out 0xed, al                             ; 9BEA
        mov dx, 0x26                             ; 9BEC
        in ax, dx                                ; 9BEF
        and ax, 0xefff                           ; 9BF0
        push ax                                  ; 9BF3
        mov dx, 0x24                             ; 9BF4
        mov ax, 0x207                            ; 9BF7
        out dx, ax                               ; 9BFA
        out 0xed, al                             ; 9BFB
        mov dx, 0x26                             ; 9BFD
        pop ax                                   ; 9C00
        out dx, ax                               ; 9C01

loc_9C02:
        ret                                      ; 9C02

; Runs from the shadow-RAM copy: if the 4 spare entries (types 44-47, E6B1-E6F0) are still zero, fill them from CMOS types 19h/1Ah via hd_autodetect_fill_entry and adjust the ROM checksum byte at F000:FFEF by the bytes written.
hd_autodetect_patch_table:
        push es                                  ; 9C03
        push ds                                  ; 9C04
        mov ax, 0xf000                           ; 9C05
        mov es, ax                               ; 9C08
        mov ds, ax                               ; 9C0A
        xor si, si                               ; 9C0C
        xor di, di                               ; 9C0E
        cld                                      ; 9C10
        call hd_spare_entries_zero_check         ; 9C11
        jne loc_9C4A                             ; 9C14
        xor cx, cx                               ; 9C18
        mov al, 0x99                             ; 9C1A
        call cmos_read_ext_type                  ; 9C1C
        jne loc_9C29                             ; 9C1F
        mov dx, 1                                ; 9C23
        call hd_autodetect_fill_entry            ; 9C26

loc_9C29:
        mov al, 0x9a                             ; 9C29
        call cmos_read_ext_type                  ; 9C2B
        jne loc_9C38                             ; 9C2E
        mov dx, 2                                ; 9C32
        call hd_autodetect_fill_entry            ; 9C35

loc_9C38:
        test dx, dx                              ; 9C38
        je loc_9C4A                              ; 9C3A
        mov ch, byte [es:0xffef]                 ; 9C3E
        sub ch, cl                               ; 9C43
        mov byte [es:0xffef], ch                 ; 9C45

loc_9C4A:
        pop ds                                   ; 9C4A
        pop es                                   ; 9C4B
        ret                                      ; 9C4C

; AL = CMOS extended type: <= 2Dh (44/45 = Auto Detected / AUTO 2) -> ata_identify_to_table; 2Eh/2Fh (User Defined / USER 2) -> copy CMOS A0h../B5h.. parameters into table entries 46/47 (E6D1/E6E1).
hd_autodetect_fill_entry:
        cld                                      ; 9C4D
        push bx                                  ; 9C4E
        push di                                  ; 9C4F
        push es                                  ; 9C50
        push ds                                  ; 9C51
        cmp al, 0x2d                             ; 9C52
        ja loc_9C5E                              ; 9C54
        call ata_identify_to_table               ; 9C58
        jmp loc_9CB6                             ; 9C5B
; [data] alignment pad (nop / xchg bx,bx)
        db 0x90 ; 9C5D .

loc_9C5E:
        mov ah, 0xa0                             ; 9C5E
        lea di, [0xe6d1]                         ; 9C60
        cmp al, 0x2e                             ; 9C64
        je loc_9C70                              ; 9C66
        mov ah, 0xb5                             ; 9C6A
        lea di, [0xe6e1]                         ; 9C6C

loc_9C70:
        mov bl, ah                               ; 9C70
        push ax                                  ; 9C72
        mov ax, 0xf000                           ; 9C73
        mov es, ax                               ; 9C76
        mov ds, ax                               ; 9C78
        pop ax                                   ; 9C7A
        call cmos_read_bl_stosb_sum              ; 9C7B
        call cmos_read_bl_stosb_sum              ; 9C7E
        call cmos_read_bl_stosb_sum              ; 9C81
        mov byte [di + 5], 8                     ; 9C84
        add cl, 8                                ; 9C88
        cmp al, 8                                ; 9C8B
        ja loc_9C98                              ; 9C8D
        mov byte [di + 5], 0                     ; 9C91
        sub cl, 8                                ; 9C95

loc_9C98:
        xor ax, ax                               ; 9C98
        stosw                                    ; 9C9A
        call cmos_read_bl_stosb_sum              ; 9C9B
        call cmos_read_bl_stosb_sum              ; 9C9E
        xor al, al                               ; 9CA1
        stosb                                    ; 9CA3
        inc di                                   ; 9CA4
        xor al, al                               ; 9CA5
        stosb                                    ; 9CA7
        stosb                                    ; 9CA8
        stosb                                    ; 9CA9
        call cmos_read_bl_stosb_sum              ; 9CAA
        call cmos_read_bl_stosb_sum              ; 9CAD
        call cmos_read_bl_stosb_sum              ; 9CB0
        xor al, al                               ; 9CB3
        stosb                                    ; 9CB5

loc_9CB6:
        pop ds                                   ; 9CB6
        pop es                                   ; 9CB7
        pop di                                   ; 9CB8
        pop bx                                   ; 9CB9
        clc                                      ; 9CBA
        ret                                      ; 9CBB

; AL = CMOS[BL++|80h] -> ES:DI, CL += AL (checksum accumulation).
cmos_read_bl_stosb_sum:
        mov al, bl                               ; 9CBC
        or al, 0x80                              ; 9CBE
        pushf                                    ; 9CC0
        cli                                      ; 9CC1
        out 0x70, al                             ; 9CC2  port 70h: CMOS index / NMI enable
        out 0xed, al                             ; 9CC4
        in al, 0x71                              ; 9CC6  port 71h: CMOS data
        popf                                     ; 9CC8
        stosb                                    ; 9CC9
        add cl, al                               ; 9CCA
        inc bl                                   ; 9CCC
        ret                                      ; 9CCE

; Read CMOS byte AL; returns it in AL (2Ch-2Fh = auto/user types).
cmos_read_ext_type:
        pushf                                    ; 9CCF
        cli                                      ; 9CD0
        out 0x70, al                             ; 9CD1  port 70h: CMOS index / NMI enable
        out 0xed, al                             ; 9CD3
        in al, 0x71                              ; 9CD5  port 71h: CMOS data
        popf                                     ; 9CD7
        cmp al, 0x2c                             ; 9CD8
        jb loc_9CE8                              ; 9CDA
        cmp al, 0x2f                             ; 9CDE
        ja loc_9CE8                              ; 9CE0
        push ax                                  ; 9CE4
        xor ax, ax                               ; 9CE5
        pop ax                                   ; 9CE7

loc_9CE8:
        ret                                      ; 9CE8

; ATA IDENTIFY DEVICE: wait DRDY (1F7h bit 6) and !BSY, 3F6h := 02h (nIEN), zero 1F1h-1F5h, 1F6h := drive<<4 (no LBA bit), 1F7h := ECh, read 256 words into a 512-byte stack buffer, then write cylinders (word 1), heads (word 3), sectors (word 6) into hd_param_table entry (AL-1), landing zone = cylinders, control byte = 8 if heads > 8; returns CL = byte sum for the checksum fix.
ata_identify_to_table:
        push bx                                  ; 9CE9
        push dx                                  ; 9CEA
        push si                                  ; 9CEB
        push ds                                  ; 9CEC
        push ax                                  ; 9CED
        mov bl, dl                               ; 9CEE
        call ata_wait_drdy                       ; 9CF0
        jb loc_9D97                              ; 9CF3
        call ata_wait_not_busy                   ; 9CF7
        jb loc_9D97                              ; 9CFA
        mov dx, 0x3f6                            ; 9CFE
        mov al, 2                                ; 9D01
        out dx, al                               ; 9D03
        mov dx, 0x1f1                            ; 9D04
        xor al, al                               ; 9D07
        mov cx, 5                                ; 9D09

loc_9D0C:
        out dx, al                               ; 9D0C
        inc dx                                   ; 9D0D
        out 0xed, al                             ; 9D0E
        loop loc_9D0C                            ; 9D10
        mov al, bl                               ; 9D12
        sub al, 1                                ; 9D14
        shl al, 4                                ; 9D16
        and al, 0x10                             ; 9D19
        out dx, al                               ; 9D1B
        out 0xed, al                             ; 9D1C
        inc dx                                   ; 9D1E
        mov al, 0xec                             ; 9D1F
        out dx, al                               ; 9D21
        mov si, sp                               ; 9D22
        sub si, 0x200                            ; 9D24
        mov bp, sp                               ; 9D28
        mov sp, si                               ; 9D2A
        mov ax, ss                               ; 9D2C
        mov ds, ax                               ; 9D2E
        mov cx, 0x100                            ; 9D30  -> setup_far_entry
        mov dx, 0x1f0                            ; 9D33

loc_9D36:
        call ata_wait_drq                        ; 9D36
        jb loc_9D97                              ; 9D39
        in ax, dx                                ; 9D3D
        mov word [si], ax                        ; 9D3E
        inc si                                   ; 9D40
        inc si                                   ; 9D41
        loop loc_9D36                            ; 9D42
        mov sp, bp                               ; 9D44
        sub si, 0x200                            ; 9D46
        mov cx, word [si + 2]                    ; 9D4A
        mov dx, word [si + 6]                    ; 9D4D
        mov bx, word [si + 0xc]                  ; 9D50
        push cs                                  ; 9D53
        pop ds                                   ; 9D54
        mov si, 0xe401                           ; 9D55
        pop ax                                   ; 9D58
        xor ah, ah                               ; 9D59
        sub ax, 1                                ; 9D5B
        shl ax, 4                                ; 9D5E
        add si, ax                               ; 9D61
        xor ax, ax                               ; 9D63
        add al, ch                               ; 9D65
        add al, cl                               ; 9D67
        add al, dl                               ; 9D69
        add al, bl                               ; 9D6B
        add al, ch                               ; 9D6D
        add al, cl                               ; 9D6F
        push ax                                  ; 9D71
        mov word [si], cx                        ; 9D72
        mov byte [si + 2], dl                    ; 9D74
        mov word [si + 0xc], cx                  ; 9D77
        mov byte [si + 0xe], bl                  ; 9D7A
        mov cl, 9                                ; 9D7D
        mov ax, dx                               ; 9D7F
        xor ah, ah                               ; 9D81
        div cl                                   ; 9D83
        shl ax, 3                                ; 9D85
        mov byte [si + 8], al                    ; 9D88
        mov ch, al                               ; 9D8B
        pop ax                                   ; 9D8D
        add al, ch                               ; 9D8E
        mov cl, al                               ; 9D90
        xor ax, ax                               ; 9D92
        jmp loc_9D9A                             ; 9D94
; [data] alignment pad (nop / xchg bx,bx)
        db 0x90 ; 9D96 .

loc_9D97:
        out 0x80, al                             ; 9D97  port 80h: POST diagnostic code
        pop ax                                   ; 9D99

loc_9D9A:
        pop ds                                   ; 9D9A
        pop si                                   ; 9D9B
        pop dx                                   ; 9D9C
        pop bx                                   ; 9D9D
        ret                                      ; 9D9E

