        push cx                                  ; 9DAC
        push bx                                  ; 9DAD
        mov dx, 0x1f7                            ; 9DAE
        mov cx, 0xffff                           ; 9DB1
        mov bx, 3                                ; 9DB4

loc_9DB7:
        push dx                                  ; 9DB7
        push cx                                  ; 9DB8
        push bx                                  ; 9DB9
        call delay_100_refresh                   ; 9DBA
        pop bx                                   ; 9DBD
        pop cx                                   ; 9DBE
        pop dx                                   ; 9DBF
        in al, dx                                ; 9DC0
        test al, 0x40                            ; 9DC1
        jne loc_9DD1                             ; 9DC3
        loop loc_9DB7                            ; 9DC7
        dec bx                                   ; 9DC9
        cmp bh, bl                               ; 9DCA
        jne loc_9DB7                             ; 9DCC
        mov al, 0x50                             ; 9DCE
        stc                                      ; 9DD0

loc_9DD1:
        pop bx                                   ; 9DD1
        pop cx                                   ; 9DD2
        pop dx                                   ; 9DD3
        ret                                      ; 9DD4

; Poll 1F7h bit 7 (BSY) clear; CF=1 AL=51h on timeout.
ata_wait_not_busy:
        push dx                                  ; 9DD5
        push cx                                  ; 9DD6
        push bx                                  ; 9DD7
        mov dx, 0x1f7                            ; 9DD8
        mov cx, 0xffff                           ; 9DDB
        mov bx, 3                                ; 9DDE

loc_9DE1:
        push dx                                  ; 9DE1
        push cx                                  ; 9DE2
        push bx                                  ; 9DE3
        call delay_100_refresh                   ; 9DE4
        pop bx                                   ; 9DE7
        pop cx                                   ; 9DE8
        pop dx                                   ; 9DE9
        in al, dx                                ; 9DEA
        test al, 0x80                            ; 9DEB
        je loc_9DFB                              ; 9DED
        loop loc_9DE1                            ; 9DF1
        dec bx                                   ; 9DF3
        cmp bh, bl                               ; 9DF4
        jne loc_9DE1                             ; 9DF6
        mov al, 0x51                             ; 9DF8
        stc                                      ; 9DFA

loc_9DFB:
        pop bx                                   ; 9DFB
        pop cx                                   ; 9DFC
        pop dx                                   ; 9DFD
        ret                                      ; 9DFE

; Poll 1F7h bit 3 (DRQ); CF=1 AL=52h on timeout.
ata_wait_drq:
        push dx                                  ; 9DFF
        push cx                                  ; 9E00
        push bx                                  ; 9E01
        mov dx, 0x1f7                            ; 9E02
        mov cx, 0xffff                           ; 9E05
        mov bx, 3                                ; 9E08

loc_9E0B:
        push dx                                  ; 9E0B
        push cx                                  ; 9E0C
        push bx                                  ; 9E0D
        call delay_100_refresh                   ; 9E0E
        pop bx                                   ; 9E11
        pop cx                                   ; 9E12
        pop dx                                   ; 9E13
        in al, dx                                ; 9E14
        test al, 8                               ; 9E15
        jne loc_9E25                             ; 9E17
        loop loc_9E0B                            ; 9E1B
        dec bx                                   ; 9E1D
        cmp bh, bl                               ; 9E1E
        jne loc_9E0B                             ; 9E20
        mov al, 0x52                             ; 9E22
        stc                                      ; 9E24

loc_9E25:
        pop bx                                   ; 9E25
        pop cx                                   ; 9E26
        pop dx                                   ; 9E27
        ret                                      ; 9E28

; AX = index -> AX = chipset register (ports 24h/26h).
chipset_reg_read_ax:
        push ax                                  ; 9E29
        cli                                      ; 9E2A
        mov dx, 0x24                             ; 9E2B
        out dx, ax                               ; 9E2E
        mov dx, 0x26                             ; 9E2F
        in ax, dx                                ; 9E32
        xchg dx, ax                              ; 9E33
        pop ax                                   ; 9E34
        ret                                      ; 9E35

; AX = index, DX = value -> chipset register.
chipset_reg_write:
        push ax                                  ; 9E36
        push dx                                  ; 9E37
        cli                                      ; 9E38
        mov dx, 0x24                             ; 9E39
        xchg dx, ax                              ; 9E3C
        out dx, ax                               ; 9E3D
        mov dx, 0x26                             ; 9E3E
        pop ax                                   ; 9E41
        out dx, ax                               ; 9E42
        xchg dx, ax                              ; 9E43
        pop ax                                   ; 9E44
        ret                                      ; 9E45

; Chipset regs 200h/207h |= 0Ch (shadow-RAM write enable bits, best guess).
chipset_200_207_bits23_set:
        push ax                                  ; 9E46
        push dx                                  ; 9E47
        mov ax, 0x200                            ; 9E48
        call chipset_reg_read_ax                 ; 9E4B
        or dl, 0xc                               ; 9E4E
        call chipset_reg_write                   ; 9E51
        mov ax, 0x207                            ; 9E54
        call chipset_reg_read_ax                 ; 9E57
        or dl, 0xc                               ; 9E5A
        call chipset_reg_write                   ; 9E5D
        pop dx                                   ; 9E60
        pop ax                                   ; 9E61
        ret                                      ; 9E62

; Chipset regs 200h/207h &= F3h.
chipset_200_207_bits23_clear:
        push ax                                  ; 9E63
        push dx                                  ; 9E64
        mov ax, 0x200                            ; 9E65
        call chipset_reg_read_ax                 ; 9E68
        and dl, 0xf3                             ; 9E6B
        call chipset_reg_write                   ; 9E6E
        mov ax, 0x207                            ; 9E71
        call chipset_reg_read_ax                 ; 9E74
        and dl, 0xf3                             ; 9E77
        call chipset_reg_write                   ; 9E7A
        pop dx                                   ; 9E7D
        pop ax                                   ; 9E7E
        ret                                      ; 9E7F

; [bp+1A] &= FEh, [bp+1B] |= 2 (request flags in the INT 13h frame).
floppy_flags_clear_bit0_set_bit9:
        and byte [bp + 0x1a], 0xfe               ; 9E80
        or byte [bp + 0x1b], 2                   ; 9E84
        ret                                      ; 9E88

; [bp+1A] |= 1 (diskette request flag).
floppy_flags_set_bit0:
        or word [bp + 0x1a], 1                   ; 9E89
        ret                                      ; 9E8D

; AL := 1 << drive ([bp+0C]).
floppy_drive_bit_mask:
        push cx                                  ; 9E8E
        mov cl, byte [bp + 0xc]                  ; 9E8F
        mov al, 1                                ; 9E92
        shl al, cl                               ; 9E94
        pop cx                                   ; 9E96
        ret                                      ; 9E97

; Byte records (09 00 DF 02 25 02 09 2A FF 50 F6 0F 06 27 80 01 ...) - keyboard-controller / speed table, format not decoded.
table_9E98:
; [data] table_9E98
        db 0x09, 0x00 ; 9E98 ..

; Built-in diskette parameter tables, 8 tables of 14 bytes (standard 11-byte DPT + max track, data rate, type): 9E9A 360K, 9EA8 360K in 1.2M drive, 9EB6 1.2M, 9EC4/9ED2 720K, 9EE0 1.44M, 9EEE 720K in 2.88M drive, 9EFC 1.44M in 2.88M drive; [bp+2] points at the one in use; A7D5/A8DE index them as (ptr-9E9Ah)/14.
diskette_param_tables:
; [data] diskette parameter tables (8 x 14 bytes)
        db 0xDF, 0x02, 0x25, 0x02, 0x09, 0x2A, 0xFF, 0x50, 0xF6, 0x0F, 0x06, 0x27, 0x80, 0x01, 0xEF, 0x02 ; 9E9A ..%..*.P...'....
        db 0x25, 0x02, 0x09, 0x2A, 0xFF, 0x50, 0xF6, 0x0F, 0x06, 0x27, 0x40, 0x02, 0xDF, 0x04, 0x25, 0x02 ; 9EAA %..*.P...'@...%.
        db 0x0F, 0x1B, 0xFF, 0x54, 0xF6, 0x0F, 0x06, 0x4F, 0x00, 0x02, 0xEF, 0x02, 0x25, 0x02, 0x09, 0x1B ; 9EBA ...T...O....%...
        db 0xFF, 0x50, 0xF6, 0x0F, 0x05, 0x4F, 0x80, 0x03, 0xEF, 0x02, 0x25, 0x02, 0x09, 0x1B, 0xFF, 0x50 ; 9ECA .P...O....%....P
        db 0xF6, 0x0F, 0x05, 0x4F, 0x80, 0x04, 0xDF, 0x04, 0x25, 0x02, 0x12, 0x1B, 0xFF, 0x6C, 0xF6, 0x0F ; 9EDA ...O....%....l..
        db 0x05, 0x4F, 0x00, 0x04, 0xE3, 0x02, 0x25, 0x02, 0x09, 0x1B, 0xFF, 0x50, 0xF6, 0x0F, 0x05, 0x4F ; 9EEA .O....%....P...O
        db 0x80, 0x06, 0xD5, 0x04, 0x25, 0x02, 0x12, 0x1B, 0xFF, 0x6C, 0xF6, 0x0F, 0x05, 0x4F, 0x00, 0x06 ; 9EFA ....%....l...O..
        db 0xAA, 0x08, 0x25, 0x02, 0x24, 0x1B, 0xFF, 0x54, 0xF6, 0x0F, 0x05, 0x4F, 0xC0, 0x06, 0x9A, 0x9E ; 9F0A ..%.$..T...O....

; ES:SI = INT 1Eh vector (0000:0078) - the active diskette parameter table.
get_diskette_param_table:
        mov es, word [cs:0x9f25]                 ; 9F1A
        les si, [es:0x78]                        ; 9F1F
        ret                                      ; 9F24

; 0000h
zero_seg_word_3:
        db 0x00, 0x00 ; 9F25 ..

; floppy_reset_controller, fdc_dumpreg_probe; 40:3F bit 7 := enhanced controller (82077-class) when the probe returned 2.
floppy_reset_and_probe_fdc:
        call floppy_reset_controller             ; 9F27
        call fdc_dumpreg_probe                   ; 9F2A
        and byte [0x43f], 0x7f                   ; 9F2D
        cmp al, 2                                ; 9F32
        jne loc_9F3B                             ; 9F34
        or byte [0x43f], 0x80                    ; 9F36

loc_9F3B:
        ret                                      ; 9F3B

; DOR (3F2h) := motor bits from 40:3F | 08h (IRQ/DMA on, reset asserted), 5-tick delay, then | 04h (reset released).
floppy_dor_reset_pulse:
        mov al, byte [0x43f]                     ; 9F3C
        rol al, 4                                ; 9F3F
