        mov al, 4                                ; 9F63
        out dx, al                               ; 9F65
        pop dx                                   ; 9F66
        ret                                      ; 9F67

; Turn the drive motor on via the digital output register (3F2h), track motor state in 40:3F/40:40 with the spin-up delay from the parameter table.
floppy_motor_on:
