        mov cl, 7                                ; A07C
        shl ax, cl                               ; A07E
        dec ax                                   ; A080
        add dx, ax                               ; A081
        jb loc_A0B2                              ; A083
        mov dx, 0xc                              ; A085
        out dx, al                               ; A088
        mov dx, 5                                ; A089
        out 0xed, al                             ; A08C
        out dx, al                               ; A08E
        xchg ah, al                              ; A08F
        out 0xed, al                             ; A091
        out dx, al                               ; A093
        mov dx, 4                                ; A094
        xchg bx, ax                              ; A097
        out 0xed, al                             ; A098
        out dx, al                               ; A09A
        xchg ah, al                              ; A09B
        out 0xed, al                             ; A09D
        out dx, al                               ; A09F
        sti                                      ; A0A0
        xchg ch, al                              ; A0A1
        mov dx, 0x81                             ; A0A3
        out dx, al                               ; A0A6
        out 0xed, al                             ; A0A7
