; [data] floppy_media_table
        db 0x00, 0x00, 0x01, 0x02, 0x03, 0x03, 0x04, 0x04, 0x02, 0x02, 0x05, 0x05, 0x07, 0x07, 0x09, 0x09 ; A7AF ................
        db 0x09, 0x09, 0x09, 0x09, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x00, 0x03, 0x03, 0x04, 0x06, 0x06 ; A7BF ................
        db 0x08, 0x08, 0x08, 0x08, 0x08, 0x08 ; A7CF ......

; Pick the parameter table / data-rate for the drive from 40:90/91 media-state bits (tables at A7AF and A7B7), store the pointer in [bp+2].
floppy_select_media_params:
        call floppy_get_drive_type               ; A7D5
        dec al                                   ; A7D8
        mov ah, al                               ; A7DA
        mov bh, 0                                ; A7DC
        mov bl, byte [bp + 0xc]                  ; A7DE
        mov bl, byte [bx + 0x490]                ; A7E1
        shr bl, 5                                ; A7E5
        mov al, byte [cs:bx - 0x5851]            ; A7E8
        mov bl, ah                               ; A7ED
        mov ah, 6                                ; A7EF
        mul ah                                   ; A7F1
        add bx, ax                               ; A7F3
        mov al, byte [cs:bx - 0x5849]            ; A7F5
        mov di, 0x9e9a                           ; A7FA
        mov ah, 0xe                              ; A7FD
        mul ah                                   ; A7FF
        add di, ax                               ; A801
        mov word [bp + 2], di                    ; A803
        jmp loc_A2BC                             ; A806

; C0 FF 60 FF 60 FF 80 - per-drive-type bytes (data-rate / step, best guess).
floppy_table_A809:
; [data] floppy_table_A809
        db 0xC0, 0xFF, 0x60, 0xFF, 0x60, 0xFF, 0x80, 0xFF ; A809 ..`.`...

; Seek to the requested cylinder (recalibrate first when the media state says the drive is uncalibrated); updates 40:94/95 current cylinder.
floppy_seek:
        movzx bx, byte [bp + 0xc]                ; A811
        call floppy_drive_type_known             ; A815
        jne loc_A81F                             ; A818
        mov byte [bx + 0x490], 0x93              ; A81A

loc_A81F:
        mov al, byte [bx + 0x490]                ; A81F
        test al, 0x10                            ; A823
        je loc_A828                              ; A825
        ret                                      ; A827

loc_A828:
        push cx                                  ; A828
        mov ch, byte [bp + 0xf]                  ; A829
        call floppy_seek_if_needed               ; A82C
        pop cx                                   ; A82F
        call floppy_motor_start_wait             ; A830
        cmp byte [0x441], 0                      ; A833
        jne loc_A873                             ; A838
        mov al, 0                                ; A83A

loc_A83C:
        movzx bx, byte [bp + 0xc]                ; A83C
        mov byte [bx + 0x490], al                ; A840
        call floppy_select_media_params          ; A844
        mov al, 0x4a                             ; A847
        call fdc_write_byte                      ; A849
        jb loc_A8C3                              ; A84C
        call fdc_write_head_drive                ; A84E
        jb loc_A8C3                              ; A851
        call floppy_wait_irq                     ; A853
        jb loc_A8C3                              ; A856
        call fdc_read_results_check              ; A858
        jb loc_A863                              ; A85B
        and byte [0x441], 0                      ; A85D
        ret                                      ; A862

loc_A863:
        cmp byte [0x441], 2                      ; A863
        je loc_A873                              ; A868
        cmp byte [0x441], 0x10                   ; A86A
        je loc_A873                              ; A86F
        jmp loc_A8C3                             ; A871

loc_A873:
        movzx bx, byte [bp + 0xc]                ; A873
        push bx                                  ; A877
        mov bl, byte [bx + 0x490]                ; A878
        shr bl, 5                                ; A87C
        mov al, byte [cs:bx - 0x57f7]            ; A87F
        pop bx                                   ; A884
        mov byte [bx + 0x490], al                ; A885
        mov ah, al                               ; A889
        and ah, 0xc0                             ; A88B
        cmp ah, 0x40                             ; A88E
        jne loc_A8B1                             ; A891
        mov ch, byte [bp + 0xf]                  ; A893
        test al, 0x20                            ; A896
        je loc_A8A3                              ; A898
        test ch, 1                               ; A89A
        je loc_A8AA                              ; A89D
        dec ch                                   ; A89F
        jmp loc_A8AA                             ; A8A1

loc_A8A3:
        test ch, 1                               ; A8A3
        jne loc_A8AA                             ; A8A6
        inc ch                                   ; A8A8

loc_A8AA:
        push ax                                  ; A8AA
        call floppy_seek_if_needed               ; A8AB
        pop ax                                   ; A8AE
        jmp loc_A83C                             ; A8AF

loc_A8B1:
        cmp al, 0xc0                             ; A8B1
        jne loc_A8BC                             ; A8B3
        test byte [0x43f], 0x80                  ; A8B5
        je loc_A873                              ; A8BA

loc_A8BC:
        cmp al, 0xff                             ; A8BC
        je loc_A8C3                              ; A8BE
        jmp loc_A83C                             ; A8C0

loc_A8C3:
        movzx bx, byte [bp + 0xc]                ; A8C3
        push word [0x441]                        ; A8C7
        call floppy_reset_controller             ; A8CB
        pop word [0x441]                         ; A8CE
        stc                                      ; A8D2
        ret                                      ; A8D3

; 93 74 15 97 97 17 97 17 D7 54 - media/data-rate parameters.
floppy_rate_table_A8D4:
; [data] floppy_rate_table_A8D4
        db 0x93, 0x74, 0x15, 0x97, 0x97, 0x17, 0x97, 0x17, 0xD7, 0x54 ; A8D4 .t.......T

; 40:90/91 := media state code for the parameter table selected in [bp+2] (table A8D4).
floppy_set_media_state_from_table:
        mov ax, word [bp + 2]                    ; A8DE
        sub ax, 0x9e9a                           ; A8E1
        mov bl, 0xe                              ; A8E4
        div bl                                   ; A8E6
        mov bl, al                               ; A8E8
        mov bh, 0                                ; A8EA
        mov al, byte [cs:bx - 0x572c]            ; A8EC
        mov bl, byte [bp + 0xc]                  ; A8F1
        mov byte [bx + 0x490], al                ; A8F4
        ret                                      ; A8F8

; Advances the media-state byte 40:490+drive to the next data-rate trial (table floppy_media_state_table).
floppy_media_state_step:
        movzx bx, byte [bp + 0xc]                ; A8F9
        and byte [bx + 0x490], 0xef              ; A8FD
        mov al, byte [bx + 0x490]                ; A902
        and al, 7                                ; A906
        cmp al, 7                                ; A908
        je loc_A91C                              ; A90A
        mov al, byte [bx + 0x490]                ; A90C
        inc al                                   ; A910
        test al, 4                               ; A912
        je loc_A91C                              ; A914
        sub al, 4                                ; A916
        mov byte [bx + 0x490], al                ; A918

loc_A91C:
        ret                                      ; A91C

; 00 00 02 03 05 08 08.
floppy_media_state_table:
; [data] floppy_media_state_table
        db 0x00, 0x00, 0x02, 0x03, 0x05, 0x08, 0x08 ; A91D .......

