        mov dh, 1                                ; A949
        mov ax, cs                               ; A94B
        jmp loc_A959                             ; A94D

loc_A94F:
        xor dh, dh                               ; A94F
        xor bx, bx                               ; A951
        xor cx, cx                               ; A953
        xor di, di                               ; A955
        xor ax, ax                               ; A957

loc_A959:
