int13f_17_set_disk_type:
        mov al, byte [bp + 0x14]                 ; A976
        dec al                                   ; A979
        jb loc_A9A3                              ; A97B
        cmp al, 3                                ; A97D
        jg loc_A9A3                              ; A97F
        mov cl, 0xe                              ; A981
        mul cl                                   ; A983
        mov di, 0x9e9a                           ; A985
