        jmp loc_A168                             ; A9AC

int13f_18_set_media_type:
        call floppy_get_drive_type               ; A9AF
        mov cx, word [bp + 0xe]                  ; A9B2
        cmp cl, 8                                ; A9B5
        jne loc_A9BC                             ; A9B8
        inc cl                                   ; A9BA

loc_A9BC:
