loc_A9BF:
        cmp ch, byte [cs:di + 0xb]               ; A9BF
        jne loc_A9D1                             ; A9C3
        cmp cl, byte [cs:di + 4]                 ; A9C5
        jne loc_A9D1                             ; A9C9
        cmp al, byte [cs:di + 0xd]               ; A9CB
        je loc_A9DF                              ; A9CF

loc_A9D1:
        add di, 0xe                              ; A9D1
        cmp di, 0x9f18                           ; A9D4
