; 03 04 06.
floppy_bytes_A9FB:
; [data] floppy_bytes_A9FB
        db 0x03, 0x04, 0x06 ; A9FB ...

; call ...; AH := 30h ... diskette status/motor handling fragment (floppy driver internals).
floppy_motor_check:
        call floppy_drive_type_known             ; A9FE
        mov ah, 0x30                             ; AA01
        je loc_AA4C                              ; AA03
        call floppy_motor_on                     ; AA05
        out 0xed, al                             ; AA08
        mov dx, 0x3f3                            ; AA0A
        in al, dx                                ; AA0D
        test al, 0x20                            ; AA0E
        mov ah, 0x30                             ; AA10
        jmp loc_AA4C                             ; AA12

; Continuation of floppy_motor_check: DIR bits 6-7 -> table A9FBh index -> drive type in [bp+14].
floppy_drive_type_resolve:
        test al, 0xc0                            ; AA14
        mov ah, 0x31                             ; AA16
        je loc_AA4C                              ; AA18
        not al                                   ; AA1A
        shr al, 6                                ; AA1C
        mov bl, al                               ; AA1F
        mov bh, 0                                ; AA21
        mov bl, byte [cs:bx - 0x5605]            ; AA23
        mov byte [bp + 0x14], bl                 ; AA28
        mov bl, al                               ; AA2B
        call floppy_get_drive_type               ; AA2D
        cmp al, 6                                ; AA30
        je loc_AA4A                              ; AA32
        cmp bl, 2                                ; AA34
        je loc_AA46                              ; AA37
        cmp al, 4                                ; AA39
        je loc_AA4A                              ; AA3B
        cmp bl, 1                                ; AA3D
        je loc_AA46                              ; AA40
        cmp al, 3                                ; AA42
        je loc_AA4A                              ; AA44

loc_AA46:
        mov ah, 0x32                             ; AA46
        jmp loc_AA4C                             ; AA48

loc_AA4A:
        mov ah, 0                                ; AA4A

loc_AA4C:
        jmp loc_A168                             ; AA4C

; AL := ~40:3E; SF = drive needs recalibration.
floppy_recal_flag_test:
        mov al, byte [0x43e]                     ; AA4F
        not al                                   ; AA52
        test al, 0x80                            ; AA54
        ret                                      ; AA56

; Unmask IRQ6, INT 15h AX=9001h (device busy), wait for 40:3E bit 7 (set by the IRQ6 handler) with a 15 x 1M refresh-cycle timeout (callback AA4F); CF = timeout.
floppy_wait_irq:
        cli                                      ; AA57
        in al, 0x21                              ; AA58  port 21h: PIC1 data/mask
        and al, 0xbf                             ; AA5A
        out 0x21, al                             ; AA5C  port 21h: PIC1 data/mask
        mov ax, 0x9001                           ; AA5E
        int 0x15                                 ; AA61  system services
        sti                                      ; AA63
        push bx                                  ; AA64
        push cx                                  ; AA65
        push dx                                  ; AA66
        mov bx, 0xf                              ; AA67
        mov cx, 0x4240                           ; AA6A
        mov dx, 0xaa4f                           ; AA6D  -> floppy_recal_flag_test
        call wait_refresh_cycles                 ; AA70
        pop dx                                   ; AA73
        pop cx                                   ; AA74
        pop bx                                   ; AA75
        je loc_AA7F                              ; AA76
        mov byte [0x441], 0x80                   ; AA78
        stc                                      ; AA7D
        ret                                      ; AA7E

loc_AA7F:
        and byte [0x43e], 0x7f                   ; AA7F
        ret                                      ; AA84

loc_AA85:
        push ax                                  ; AA85
        push dx                                  ; AA86
        push ds                                  ; AA87
        mov al, 0x20                             ; AA88
        out 0x20, al                             ; AA8A  port 20h: PIC1 command
        mov ds, word [cs:0x9f25]                 ; AA8C
        or byte [0x43e], 0x80                    ; AA91
        mov ax, 0x9101                           ; AA96
        int 0x15                                 ; AA99  system services
        pop ds                                   ; AA9B
        pop dx                                   ; AA9C
        pop ax                                   ; AA9D
        iret                                     ; AA9E

int13f_15_get_disk_type:
        call floppy_get_drive_type               ; AA9F
        mov ah, 0                                ; AAA2
        or al, al                                ; AAA4
        je loc_AAB0                              ; AAA6
        inc ah                                   ; AAA8
        cmp al, 1                                ; AAAA
