; DIR 3F7h bit 7 (disk change): when set, floppy_media_state_step and returns AL=80h with SF.
floppy_disk_change_check:
        mov dx, 0x3f7                            ; AAB8
        in al, dx                                ; AABB
        or al, al                                ; AABC
        jns loc_AAC7                             ; AABE
        call floppy_media_state_step             ; AAC0
        mov al, 0x80                             ; AAC3
        or al, al                                ; AAC5

loc_AAC7:
