; Writes a code descriptor at ES:DI: limit FFFFh, base CS<<4 + BP, type 9Bh.
gdt_build_code_descriptor:
        mov ch, 0x9b                             ; C311
        mov ax, cs                               ; C313
        mov bp, 0                                ; C315
        push ax                                  ; C318
        push cx                                  ; C319
        mov cl, 4                                ; C31A
        rol ax, cl                               ; C31C
        mov ch, al                               ; C31E
        and ch, 0xf                              ; C320
        and al, 0xf0                             ; C323
        add ax, bp                               ; C325
        adc ch, 0                                ; C327
        mov word [es:di], 0xffff                 ; C32A
        mov word [es:di + 2], ax                 ; C32F
        mov byte [es:di + 4], ch                 ; C333
        pop cx                                   ; C337
        mov byte [es:di + 5], ch                 ; C338
        mov word [es:di + 6], 0                  ; C33C
        pop ax                                   ; C342
        ret                                      ; C343

; ICW1 11h, ICW2 BH, ICW3 AH, ICW4 01h to the PIC at DX/DX+1 (port EDh delays).
pic_init_icw:
        mov al, 0x11                             ; C344
        out 0xed, al                             ; C346
        out dx, al                               ; C348
        inc dx                                   ; C349
        mov al, bh                               ; C34A
        out 0xed, al                             ; C34C
        out dx, al                               ; C34E
        mov al, ah                               ; C34F
        out 0xed, al                             ; C351
        out dx, al                               ; C353
        mov al, 1                                ; C354
        out 0xed, al                             ; C356
        out dx, al                               ; C358
        ret                                      ; C359

; Latches PIT channel 0 (43h := 00h) and reads the count into BX.
pit_ch0_latch_read:
        push dx                                  ; C35A
        mov dx, 0x43                             ; C35B
        mov al, 0                                ; C35E
        out 0xed, al                             ; C360
        out dx, al                               ; C362
        dec dx                                   ; C363
        dec dx                                   ; C364
        dec dx                                   ; C365
        out 0xed, al                             ; C366
        in al, dx                                ; C368
        mov bl, al                               ; C369
        in al, dx                                ; C36B
        mov bh, al                               ; C36C
        pop dx                                   ; C36E
        ret                                      ; C36F

; AL := 40:B5 >> 3 (cache-control bits), AH := raw byte (bit 7 = cache currently enabled).
cache_flags_from_4B5:
        push ds                                  ; C370
        mov ds, word [cs:0xd49f]                 ; C371
        mov al, byte [0x4b5]                     ; C376
        pop ds                                   ; C379
        mov ah, al                               ; C37A
        shr al, 3                                ; C37C
        test ah, 0x80                            ; C37F
        jne loc_C387                             ; C382
        stc                                      ; C386

loc_C387:
        ret                                      ; C387

; Clears 40:B5 bits 3/4/7 and ROM-stack calls C4B7 (power-management/chipset early init), then returns.
post_early_pm_init:
