        test bl, 4                               ; CAF7
        je loc_CB10                              ; CAFA
        cmp al, 0x3d                             ; CAFC
        je hotkey_setup                          ; CAFE
        cmp al, 0x3e                             ; CB02
        je hotkey_display_toggle                 ; CB04
        cmp al, 0x42                             ; CB08
        je hotkey_power_meter                    ; CB0A
        pop bx                                   ; CB0E
        ret                                      ; CB0F

loc_CB10:
        pop bx                                   ; CB10
        add sp, 2                                ; CB11
        stc                                      ; CB14
        retf 2                                   ; CB15

; Unmask IRQ1 and return CF=0 (key consumed) from the intercept.
hotkey_exit_consumed:
