        push ax                                  ; CB19
        in al, 0x21                              ; CB1A  port 21h: PIC1 data/mask
        jmp loc_CB1E                             ; CB1C

loc_CB1E:
        jmp loc_CB20                             ; CB1E

loc_CB20:
        and al, 0xfd                             ; CB20
        out 0x21, al                             ; CB22  port 21h: PIC1 data/mask
        pop ax                                   ; CB24
        add sp, 2                                ; CB25
        clc                                      ; CB28
        retf 2                                   ; CB29

; Ctrl+Alt+F3 / Fn code 65h: if MISER present and SETUP not active, set 40:B6 bit1, flush keyboard buffer, clear Ctrl/Alt state, far call MISER API 34h (SETUP), then clear the flag.
hotkey_setup:
        push ax                                  ; CB2C
        push bx                                  ; CB2D
        push cx                                  ; CB2E
        push dx                                  ; CB2F
        push ds                                  ; CB30
        push es                                  ; CB31
        call miser_present_check                 ; CB32
        jne loc_CB7C                             ; CB35
        call setup_hotkey_flag_set               ; CB37
        push bx                                  ; CB3A
        push ds                                  ; CB3B
        mov bx, 0                                ; CB3C
        mov ds, bx                               ; CB3F
        mov bx, word [0x41a]                     ; CB41
        mov word [0x41c], bx                     ; CB45
        mov bx, word [0x417]                     ; CB49
        and bx, 0xfcf3                           ; CB4D
        mov word [0x417], bx                     ; CB51
        pop ds                                   ; CB55
        pop bx                                   ; CB56
        db 0x9A, 0x34, 0x00, 0x00, 0xE8          ; CB57  lcall E800:0034 ; far call outside module
