        push bx                                  ; CB5F
        push ds                                  ; CB60
        mov bx, 0                                ; CB61
        mov ds, bx                               ; CB64
        mov bx, word [0x41a]                     ; CB66
        mov word [0x41c], bx                     ; CB6A
        mov bx, word [0x417]                     ; CB6E
        and bx, 0xfcf3                           ; CB72
        mov word [0x417], bx                     ; CB76
        pop ds                                   ; CB7A
        pop bx                                   ; CB7B

loc_CB7C:
        pop es                                   ; CB7C
        pop ds                                   ; CB7D
        pop dx                                   ; CB7E

loc_CB7F:
        pop cx                                   ; CB7F
        pop bx                                   ; CB80
        pop ax                                   ; CB81
        jmp hotkey_exit_consumed                 ; CB82

; Ctrl+Alt+F4 / Fn code 66h: chipset reg 9 bit 9 := 0, INT 10h AX=5F50h (panel info), choose next device (DL bit3 -> CRT=0, DL bit1 -> both=2, else LCD=1), INT 10h AX=5F51h BL=device, delay, chipset reg 9 bit 9 := 1.
hotkey_display_toggle:
