        push bx                                  ; CB85
        push cx                                  ; CB86
        call miser_present_check                 ; CB87
        jne loc_CB7F                             ; CB8A
        push ax                                  ; CB8C
        push bx                                  ; CB8D
        mov ax, 9                                ; CB8E
        call chipset_reg_read_bx                 ; CB91
        and bh, 0xfd                             ; CB94
        call chipset_reg_write_bx                ; CB97
        pop bx                                   ; CB9A
        pop ax                                   ; CB9B
        mov ax, 0x5f50                           ; CB9C
