        test dl, 8                               ; CBA1
        jne loc_CBBB                             ; CBA4
        test dl, 2                               ; CBA8
        jne loc_CBB5                             ; CBAB
        mov bx, 0x101                            ; CBAF
        jmp loc_CBBE                             ; CBB2
; [data] alignment pad (nop / xchg bx,bx)
