; 40:B6 bit1 := 1 (SETUP entered via hot key).
setup_hotkey_flag_set:
        push ds                                  ; CC19
        mov ax, 0x40                             ; CC1A
        mov ds, ax                               ; CC1D
        or byte [0xb6], 2                        ; CC1F
        pop ds                                   ; CC24
        ret                                      ; CC25

; 40:B6 bit1 := 0.
setup_hotkey_flag_clear:
