        mov ax, 0x40                             ; CC27
        mov ds, ax                               ; CC2A
        and byte [0xb6], 0xfd                    ; CC2C
        pop ds                                   ; CC31
        ret                                      ; CC32

; If SETUP is not active, far call MISER API 38h; ZF result used by the hot-key handlers.
miser_present_check:
        call setup_active_check                  ; CC33
        jne loc_CC3F                             ; CC36
        db 0x9A, 0x38, 0x00, 0x00, 0xE8          ; CC3A  lcall E800:0038 ; far call outside module

loc_CC3F:
        ret                                      ; CC3F

; ZF from 40:B5 bit0 (SETUP running).
setup_active_check:
        push ds                                  ; CC40
        push ax                                  ; CC41
        mov ax, 0x40                             ; CC42
        mov ds, ax                               ; CC45
        test byte [0xb5], 1                      ; CC47
        pop ax                                   ; CC4C
        pop ds                                   ; CC4D
        ret                                      ; CC4E

; ZF = !(40:B6 bit 2).
bda_B6_bit2_test:
