        push ax                                  ; CC50
        mov ax, 0x40                             ; CC51
        mov ds, ax                               ; CC54
        test byte [0xb6], 4                      ; CC56
        pop ax                                   ; CC5B
        pop ds                                   ; CC5C
        ret                                      ; CC5D

; Tests 40:B6 bit 2 (best guess: power-meter display permitted / battery system present).
power_meter_allowed_check:
        push ds                                  ; CC5E
        push ax                                  ; CC5F
        push bx                                  ; CC60
        mov ax, 0x40                             ; CC61
        mov ds, ax                               ; CC64
        test byte [0xb7], 1                      ; CC66
        jne loc_CC77                             ; CC6B
        mov ah, 0xf                              ; CC6F
        int 0x10                                 ; CC71  video
        not al                                   ; CC73
        test al, 2                               ; CC75

loc_CC77:
        pop bx                                   ; CC77
        pop ax                                   ; CC78
        pop ds                                   ; CC79
        ret                                      ; CC7A

; Called before MISER API 30h (POWER METER).
pre_power_meter_hook:
        push ds                                  ; CC7B
        push ax                                  ; CC7C
        mov ax, 0x40                             ; CC7D
        mov ds, ax                               ; CC80
        or byte [0xb7], 1                        ; CC82
        or byte [0xb5], 1                        ; CC87
        pop ax                                   ; CC8C
        pop ds                                   ; CC8D
        ret                                      ; CC8E

; Called after MISER API 30h returns.
post_power_meter_hook:
