        push ax                                  ; CC90
        mov ax, 0x40                             ; CC91
        mov ds, ax                               ; CC94
        and byte [0xb7], 0xfe                    ; CC96
        and byte [0xb5], 0xfe                    ; CC9B
        pop ax                                   ; CCA0
        pop ds                                   ; CCA1
        ret                                      ; CCA2

; AX = index -> BX = chipset register value (ports 24h/26h).
chipset_reg_read_bx:
        out 0x24, ax                             ; CCA3
        xchg bx, ax                              ; CCA5
        jmp loc_CCA8                             ; CCA6

loc_CCA8:
        jmp loc_CCAA                             ; CCA8

loc_CCAA:
        in ax, 0x26                              ; CCAA
        xchg bx, ax                              ; CCAC
        ret                                      ; CCAD

; AX = index, BX = value -> chipset register.
chipset_reg_write_bx:
        out 0x24, ax                             ; CCAE
        xchg bx, ax                              ; CCB0
        jmp loc_CCB3                             ; CCB1

loc_CCB3:
        jmp loc_CCB5                             ; CCB3

loc_CCB5:
        out 0x26, ax                             ; CCB5
        xchg bx, ax                              ; CCB7
        ret                                      ; CCB8

; shl eax,16; chipset reg 9 (24h/26h) then reg 3 written.
chipset_reg9_reg3_write:
        shl eax, 0x10                            ; CCB9
        mov ax, 9                                ; CCBD
        out 0x24, ax                             ; CCC0
        jmp loc_CCC4                             ; CCC2

loc_CCC4:
        jmp loc_CCC6                             ; CCC4

loc_CCC6:
        mov ax, 3                                ; CCC6
        out 0x26, ax                             ; CCC9
        jmp loc_CCCD                             ; CCCB

loc_CCCD:
        shr eax, 0x10                            ; CCCD
        jmp bx                                   ; CCD1  return via register

; Copies CMOS 3Fh to I/O port 1FFh and programs chipset registers 9.. from CMOS settings.
platform_cfg_from_cmos_3F:
