        push bx                                  ; CD1F
        mov ax, 9                                ; CD20
        mov bx, 0x21f                            ; CD23
        call chipset_reg_write_bx                ; CD26
        pop bx                                   ; CD29
        pop ax                                   ; CD2A
        ret                                      ; CD2B

