; AL=index -> port 26Eh, returns AL from 26Fh (Super I/O configuration read).
superio_read_reg:
        cli                                      ; CDF6
        mov dx, 0x26e                            ; CDF7
        out dx, al                               ; CDFA
        out 0xed, al                             ; CDFB
