        sub si, ax                               ; DBB2
        sub si, di                               ; DBB4
        mov ax, si                               ; DBB6
        mov dx, 0x20bd                           ; DBB8
        mul dx                                   ; DBBB
        mov bx, 0x2710                           ; DBBD
        div bx                                   ; DBC0
        mov bx, ax                               ; DBC2
        mov ax, 0x86a0                           ; DBC4
        mov dx, 1                                ; DBC7
        div bx                                   ; DBCA
        ret                                      ; DBCC

; Walk (threshold,value) byte pairs at DC09 to pick a value for chipset register 300h from AL.
chipset_speed_table_program:
        mov bx, 0xdc09                           ; DBCD

loc_DBD0:
        cmp al, byte [cs:bx]                     ; DBD0
        jae loc_DBE3                             ; DBD5
        add bx, 2                                ; DBD7
        cmp byte [cs:bx], 0                      ; DBDB
        jne loc_DBD0                             ; DBE1

loc_DBE3:
        mov cl, byte [cs:bx + 1]                 ; DBE3
        mov dx, 0x24                             ; DBE8
        mov ax, 0x300                            ; DBEB
        out dx, ax                               ; DBEE
        out 0xed, al                             ; DBEF
        mov dx, 0x26                             ; DBF1
        in ax, dx                                ; DBF4
        and al, 0xf8                             ; DBF5
        or al, cl                                ; DBF7
        push ax                                  ; DBF9
        mov dx, 0x24                             ; DBFA
        mov ax, 0x300                            ; DBFD
        out dx, ax                               ; DC00
        out 0xed, al                             ; DC01
        mov dx, 0x26                             ; DC03
        pop ax                                   ; DC06
        out dx, ax                               ; DC07
        ret                                      ; DC08

; Seven word pairs 2C07h 2407h 2006h 1604h 1203h 0E02h 0002h - cursor start/end per character height (best guess).
cursor_shape_table:
; [data] cursor_shape_table
        db 0x2C, 0x07, 0x24, 0x07, 0x20, 0x06, 0x16, 0x04, 0x12, 0x03, 0x0E, 0x02, 0x00, 0x02 ; DC09 ,.$. .........
