; Classic IBM INT 1Ah (time of day) entry.
int1A_time_entry:
        jmp loc_CF2D                             ; FE6E
; [data] FFh fill (gap between fixed entry points)
        times 52 db 0xFF                     ; FE71 fill

; Classic IBM INT 08h (timer IRQ0) entry.
int08_timer_irq_entry:
        jmp loc_CF99                             ; FEA5
; [data] FFh fill (gap between fixed entry points)
        times 75 db 0xFF                     ; FEA8 fill

; Table of 24 near offsets used to initialise INT 08h..1Fh vectors (segment F000).
ivt_init_08_1F:
; [data] table ivt_init_08_1F (24 near ptrs)
        db 0xA5, 0xFE, 0x87, 0xE9, 0x33, 0xFF, 0x33, 0xFF, 0x33, 0xFF, 0x33, 0xFF, 0x57, 0xEF, 0x43, 0xFF ; FEF3 ....3.3.3.3.W.C.
        db 0x65, 0xF0, 0x4D, 0xF8, 0x41, 0xF8, 0x59, 0xEC, 0x39, 0xE7, 0x59, 0xF8, 0x2E, 0xE8, 0xD2, 0xEF ; FF03 e.M.A.Y.9.Y.....
        db 0x36, 0x7A, 0xF2, 0xE6, 0x6E, 0xFE, 0x53, 0xFF, 0x53, 0xFF, 0xA4, 0xF0, 0xC7, 0xEF, 0x00, 0x00 ; FF13 6z..n.S.S.......

; Table of 8 near offsets used to initialise INT 70h..77h (slave PIC) vectors.
ivt_init_70_77:
; [data] table ivt_init_70_77 (8 near ptrs)
        db 0xCF, 0xD0, 0x64, 0xD5, 0x33, 0xFF, 0x33, 0xFF, 0x4D, 0xC6, 0x53, 0xD5, 0x33, 0xFF, 0x43, 0xFF ; FF23 ..d.3.3.M.S.3.C.

; Default handler for unused IRQs: sends EOI to both PICs, IRET.
int_default_irq_handler:
        jmp int_default_handler                  ; FF33
        times 13 db 0xFF                     ; FF36 fill

; Second default IRQ handler variant.
int_default_irq_handler_2:
        test byte [cs:0xaf45], 0x20              ; FF43
        je int_default_irq_handler               ; FF49
        push ax                                  ; FF4B
        mov al, 0x20                             ; FF4C
        out 0xa0, al                             ; FF4E  port A0h: PIC2 command
        out 0x20, al                             ; FF50  port 20h: PIC1 command
        pop ax                                   ; FF52

; Classic IBM FF53: IRET stub for INT 1Bh/1Ch etc.
int_dummy_iret:
        iret                                     ; FF53

; Classic IBM INT 05h (print screen) entry.
int05_print_screen_entry:
        jmp loc_D867                             ; FF54
        db 0xFF, 0xFF, 0xFF ; FF57 ...

; call sub_D1C6; retf (Phoenix far-callable stub).
fixed_entry_FF5A:
        call delay_100_refresh                   ; FF5A
        retf                                     ; FF5D
        db 0xFF, 0xFF ; FF5E ..

; call sub_8695; retf.
fixed_entry_FF60:
        call int15_4F_setup_hotkey_check         ; FF60
        retf                                     ; FF63

; Far pointer F000:ACFB -> rom_option_far_ptr_table.
rom_option_table_far_ptr:
; [data] rom_option_table_far_ptr
        db 0xFB, 0xAC, 0x00, 0xF0 ; FF64 ....

; ret.
ret_FF68:
        ret                                      ; FF68
        times 14 db 0xFF                     ; FF69 fill
; [data] fill
        db 0xFF ; FF77 .

; call sub_8656; retf.
fixed_entry_FF77:
        call cpu_speed_get_level                 ; FF78
        retf                                     ; FF7B

; call sub_8619; retf.
fixed_entry_FF7C:
        call cpu_speed_set_level                 ; FF7C
        retf                                     ; FF7F

; 2 bytes before fixed_entry_FF82.
bytes_FF80:
; [data] bytes_FF80
        db 0x86, 0x03 ; FF80 ..

; call sub_CE49; retf.
fixed_entry_FF82:
        call int15_24_a20_gate_service           ; FF82
        retf                                     ; FF85
; [data] fill
        times 54 db 0xFF                     ; FF86 fill
        db 0x30, 0x30, 0x37, 0x37, 0x2F, 0x2F, 0x30, 0x30, 0x36, 0x36, 0x2F, 0x2F, 0x39, 0x39, 0x34, 0x34 ; FFBC 0077//0066//9944
        db 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x01, 0x03, 0x03 ; FFCC ................
        db 0xFF, 0xFF, 0xFF, 0xFF, 0xEA, 0x30, 0x00, 0x00, 0xE8, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF ; FFDC .....0..........
        db 0x00, 0x00, 0xD1 ; FFEC ...

; Byte adjusted by hd_autodetect_patch_table so that the shadow copy of F000 keeps its 8-bit checksum after the disk table is patched.
rom_checksum_adjust_byte:
        db 0x00 ; FFEF .

; CPU reset lands here (F000:FFF0). Far jump to POST entry.
reset_vector:
        jmp 0xF000:0xE05B                        ; FFF0

; ASCII release date 'MM/DD/YY' (Phoenix placeholder 04/19/90).
bios_date:
; [data] release date
; [data] string
        db 0x30, 0x34, 0x2F, 0x31, 0x39, 0x2F, 0x39, 0x30 ; FFF5 04/19/90
; [data] unused byte, model byte FCh, checksum byte
        db 0xFF ; FFFD .

; FCh = IBM AT class
model_byte:
        db 0xFC, 0x00 ; FFFE ..
